function tierStyle(tier: AchievementTier): string {
  if (tier === "gold") return "bg-amber-100 text-amber-700";
  if (tier === "diamond") return "bg-cyan-100 text-cyan-700";
  if (tier === "special") return "bg-purple-100 text-purple-700";
  if (tier === "silver") return "bg-slate-100 text-slate-700";
  return "bg-orange-100 text-orange-700";
}

